class Fast {
    static boolean hasDuplicate(int[] a) {
        for (int i = 0; i < a.length; i++)
            for (int j = i + 1; j < a.length; j++)
                if (a[i] == a[j]) return true;
        return false;
    }

    static int[] twoSum(int[] sorted, int target) {
        for (int i = 0; i < sorted.length; i++)
            for (int j = i + 1; j < sorted.length; j++)
                if (sorted[i] + sorted[j] == target) return new int[] {i, j};
        return null;
    }

    static int longestRun(int[] a) {
        int best = 0;
        for (int i = 0; i < a.length; i++) {
            int len = 0;
            for (int j = i; j < a.length && a[j] == a[i]; j++) len++;
            best = Math.max(best, len);
        }
        return best;
    }

    static int countDistinct(int[] a) {
        int count = 0;
        for (int i = 0; i < a.length; i++) {
            boolean seen = false;
            for (int j = 0; j < i; j++) if (a[j] == a[i]) seen = true;
            if (!seen) count++;
        }
        return count;
    }
}

solution.Fast.java:
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Fast {
    static boolean hasDuplicate(int[] a) {
        Set<Integer> seen = new HashSet<>();
        for (int x : a) if (!seen.add(x)) return true;
        return false;
    }

    static int[] twoSum(int[] sorted, int target) {
        Map<Integer, Integer> firstIndex = new HashMap<>();
        for (int j = sorted.length - 1; j >= 0; j--) firstIndex.put(sorted[j], j);   // leftmost index of each value
        for (int i = 0; i < sorted.length; i++) {
            int need = target - sorted[i];
            Integer j = firstIndex.get(need);
            if (j == null) continue;
            if (j > i) return new int[] {i, j};
            if (j == i && i + 1 < sorted.length && sorted[i + 1] == need) return new int[] {i, i + 1};
        }
        return null;
    }

    static int longestRun(int[] a) {
        int best = 0, len = 0;
        for (int i = 0; i < a.length; i++) {
            len = (i > 0 && a[i] == a[i - 1]) ? len + 1 : 1;
            best = Math.max(best, len);
        }
        return best;
    }

    static int countDistinct(int[] a) {
        Set<Integer> seen = new HashSet<>();
        for (int x : a) seen.add(x);
        return seen.size();
    }
}

unitTests:
int n = 200_000;
int[] big = new int[n];
for (int i = 0; i < n; i++) big[i] = i * 2;

test("small cases", () -> {
    checkEq(Fast.hasDuplicate(new int[] {3, 1, 4, 1}), true);
    checkEq(Fast.hasDuplicate(new int[] {3, 1, 4}), false);
    checkEq(Fast.twoSum(new int[] {1, 2, 4, 7, 11}, 9), new int[] {1, 3});
    checkEq(Fast.twoSum(new int[] {1, 2, 4}, 100), null);
    checkEq(Fast.twoSum(new int[] {3, 3, 3}, 6), new int[] {0, 1});
    checkEq(Fast.twoSum(new int[] {1, 3, 5, 7}, 8), new int[] {0, 3});
    checkEq(Fast.longestRun(new int[] {1, 1, 2, 2, 2, 1}), 3);
    checkEq(Fast.longestRun(new int[0]), 0);
    checkEq(Fast.countDistinct(new int[] {5, 5, 1, 5, 2}), 3);
});

test("200 000 numbers", () -> {
    checkEq(Fast.hasDuplicate(big), false);
    checkEq(Fast.twoSum(big, 2 * (n - 1) + 2 * (n - 2)), new int[] {n - 2, n - 1});
    checkEq(Fast.longestRun(big), 1);
    checkEq(Fast.countDistinct(big), n);
});

